-- INVENTORY MANAGEMENT SYSTEM
-- DATA-ONLY SQL FILE FOR YOUR ALREADY-CREATED ONCOMPILER TABLES
-- Do NOT run the CREATE TABLE script again.
-- Insert order: Region -> Warehouse -> Product -> Customer -> Employee -> Inventory -> Orders -> OrderDetails


-- Region: 400 records

-- Warehouse: 400 records

-- Product: 400 records

-- Customer: 400 records

-- Employee: 400 records

-- Inventory: 400 records

-- Orders: 400 records

-- OrderDetails: 400 records

-- ============================================================
-- VERIFY RECORD COUNTS
-- Every table should show 400.
-- ============================================================
SELECT 'Region' AS TableName, COUNT(*) AS RecordCount FROM Region
UNION ALL SELECT 'Warehouse', COUNT(*) FROM Warehouse
UNION ALL SELECT 'Product', COUNT(*) FROM Product
UNION ALL SELECT 'Customer', COUNT(*) FROM Customer
UNION ALL SELECT 'Employee', COUNT(*) FROM Employee
UNION ALL SELECT 'Inventory', COUNT(*) FROM Inventory
UNION ALL SELECT 'Orders', COUNT(*) FROM Orders
UNION ALL SELECT 'OrderDetails', COUNT(*) FROM OrderDetails;
